INSERT INTO plans (id,name,arabic_name,description,price,currency,duration_days,features,enabled,sort_order) VALUES ('individual-monthly','NASAQ Individual Monthly','ترخيص فردي - شهري','ترخيص رقمي فردي لمنصة نَسَق - وصول كامل لمدة 30 يومًا',79,'SAR',30,'["القوالب الكاملة المتميزة","تصدير حتى 300 DPI بلا علامة مائية","عدة تطبيقات هوية (Brand Kit) كاملة","قفل العناصر وحماية التصميم","تحديثات النسخة المرخصة"]'::jsonb,true,10) ON CONFLICT (id) DO UPDATE SET name=excluded.name,arabic_name=excluded.arabic_name,description=excluded.description,price=excluded.price,currency=excluded.currency,duration_days=excluded.duration_days,features=excluded.features,updated_at=now();
