INSERT INTO plans (id,name,arabic_name,description,price,currency,duration_days,features,enabled,sort_order) VALUES ('team-monthly','NASAQ Team Monthly','ترخيص فريق - شهري','ترخيص رقمي لفرق العمل لمنصة نَسَق - وصول كامل لمدة 30 يومًا',199,'SAR',30,'["جميع مزايا النسخة المتقدمة","ميزات الفريق ومساحة العمل المشتركة","تفعيل التراخيص عبر أكواد سريعة","استيراد وتصدير حزمة الهوية الموحدة","تصدير PDF عالي الدقة 300 DPI بدون علامة مائية","أولوية الدعم الفني"]'::jsonb,true,30) ON CONFLICT (id) DO UPDATE SET name=excluded.name,arabic_name=excluded.arabic_name,description=excluded.description,price=excluded.price,currency=excluded.currency,duration_days=excluded.duration_days,features=excluded.features,updated_at=now();
